def f(N: int, edges: List[Tuple[int, int, int]], Q: int, K: int, queries: List[Tuple[int, int]]):
    adj = [[] for _ in range(N+1)]
    visited = [0]*(N+1)
    for a, b, c in edges:
        adj[a].append((b,c))
        adj[b].append((a,c))
    def dfs(node, path):
        visited[node] = 1
        path.append(node)
        if node == K:
            return path
        for neib, wei in adj[node]:
            if not visited[neib]:
                path = dfs(neib, path)
                if path is not None:
                    return path
        path.pop()
        return None
    ans = []
    for x, y in queries:
        path = dfs(x, [])
        if path is None:
            ans.append('NO')
        else:
            if y in path:
                ans.append('YES')
            else:
                ans.append('NO')
    return ans
```

